create extension if not exists pgcrypto;
create table if not exists public.accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,type text not null default 'cash',opening_balance numeric(18,2) not null default 0,created_at timestamptz default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,type text not null check(type in('income','expense')),created_at timestamptz default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.accounts(id),category_id uuid references public.categories(id),type text not null check(type in('income','expense')),amount numeric(18,2) not null check(amount>0),description text,transaction_date date not null default current_date,created_at timestamptz default now());
create table if not exists public.budgets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category_id uuid not null references public.categories(id),month date not null,amount numeric(18,2) not null check(amount>=0));
create table if not exists public.telegram_users(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,telegram_chat_id bigint unique not null,telegram_username text,created_at timestamptz default now());
alter table public.accounts enable row level security;alter table public.categories enable row level security;alter table public.transactions enable row level security;alter table public.budgets enable row level security;alter table public.telegram_users enable row level security;
create policy "own accounts" on public.accounts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own categories" on public.categories for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own transactions" on public.transactions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own budgets" on public.budgets for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own telegram users" on public.telegram_users for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
